char* safeStrncpy(char* dest, const char* src, size_t destSize) {
    if (!dest || destSize == 0) return dest;
    size_t i = 0;
    while (i < destSize - 1 && src[i] != '\0') {
        dest[i] = src[i];
        i++;
    }
    dest[i] = '\0';
    return dest;
}

char* safeStrcat(char* dest, const char* src, size_t destSize) {
    if (!dest || destSize == 0) return dest;
    size_t len = 0;
    while (len < destSize && dest[len] != '\0') len++;
    if (len >= destSize - 1) return dest;
    size_t i = 0;
    while (len + i < destSize - 1 && src[i] != '\0') {
        dest[len + i] = src[i];
        i++;
    }
    dest[len + i] = '\0';
    return dest;
}

char* trimWhitespace(char* str) {
    if (!str) return NULL;
    while (*str == ' ' || *str == '\t' || *str == '\n' || *str == '\r') str++;
    if (*str == '\0') return str;
    char* end = str;
    while (*end) end++;
    end--;
    while (end > str && (*end == ' ' || *end == '\t' || *end == '\n' || *end == '\r')) end--;
    *(end + 1) = '\0';
    return str;
}

int parseInteger(const char* str, int* outVal) {
    if (!str || !outVal) return 0;
    while (*str == ' ') str++;
    int sign = 1;
    if (*str == '-') { sign = -1; str++; } else if (*str == '+') str++;
    if (*str < '0' || *str > '9') return 0;
    long long val = 0;
    while (*str >= '0' && *str <= '9') {
        val = val * 10 + (*str - '0');
        str++;
    }
    *outVal = (int)(val * sign);
    return 1;
}

